import sys

def count_trailing_zeros_in_factorial(n: int) -> int:
    """Count trailing zeros in n! by counting factors of 5."""
    count = 0
    power_of_5 = 5
    while power_of_5 <= n:
        count += n // power_of_5
        power_of_5 *= 5
    return count

if __name__ == "__main__":
    data = sys.stdin.read().strip()
    if not data:
        print(0)
    else:
        n = int(data)
        print(count_trailing_zeros_in_factorial(n))

