            # Try each possible root k in [l, r]
            for k in range(l, r+1):
                left_ok = (k == l) or dp[l][k-1][1]  # right child of left subtree
                right_ok = (k == r) or dp[k+1][r][0]  # left child of right subtree

                if left_ok and right_ok:
                    # Check connection to parent if exists
