def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Precompute GCD > 1 adjacency matrix
    adj = [[False]*n for _ in range(n)]
    for i in range(n):
        for j in range(i+1, n):
            if math.gcd(a[i], a[j]) > 1:
                adj[i][j] = adj[j][i] = True

    # DP[l][r][0] = can build BST for segment [l, r] with root connected to l-1
    # DP[l][r][1] = can build BST for segment [l, r] with root connected to r+1
    dp = [[[False, False] for _ in range(n)] for _ in range(n)]

    # Initialize single nodes
    for i in range(n):
        # As leaf nodes, they can connect to parent on either side
        dp[i][i][0] = True  # can connect to left parent
        dp[i][i][1] = True  # can connect to right parent

    # Fill DP for increasing segment lengths
    for length in range(2, n+1):
        for l in range(n-length+1):
            r = l + length - 1
            # Try each possible root k in [l, r]
            for k in range(l, r+1):
                # Check if left subtree [l, k-1] is valid
                left_ok = (k == l) or dp[l][k-1][1]  # root connects to k (right side)
                # Check if right subtree [k+1, r] is valid
                right_ok = (k == r) or dp[k+1][r][0]  # root connects to k (left side)

                if left_ok and right_ok:
                    # Check connection to left parent (l-1)
                    if l == 0 or adj[k][l-1]:
                        dp[l][r][0] = True
                    # Check connection to right parent (r+1)
                    if r == n-1 or adj[k][r+1]:
                        dp[l][r][1] = True

                if dp[l][r][0] and dp[l][r][1]:
                    break

    # Check if full tree [0, n-1] can be built with any root
    # For full tree, no external parent exists
    for k in range(n):
        left_ok = (k == 0) or dp[0][k-1][1]
        right_ok = (k == n-1) or dp[k+1][n-1][0]
        if left_ok and right_ok:
            print("Yes")
            return

    print("No")

