from collections import deque

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    k = int(next(it))

    main_courses = [int(next(it)) for _ in range(k)]

    # Build forward graph (prerequisites) and reverse graph (dependents)
    forward = [[] for _ in range(n + 1)]
    reverse = [[] for _ in range(n + 1)]
    indegree = [0] * (n + 1)

    for i in range(1, n + 1):
        t = int(next(it))
        indegree[i] = t
        for _ in range(t):
            prereq = int(next(it))
            forward[prereq].append(i)  # prereq -> i
            reverse[i].append(prereq)  # i depends on prereq

    # Step 1: Find all necessary courses via reverse BFS from main courses
    necessary = [False] * (n + 1)
    queue = deque(main_courses)
    for course in main_courses:
        necessary[course] = True

    while queue:
        course = queue.popleft()
        for prereq in reverse[course]:
            if not necessary[prereq]:
                necessary[prereq] = True
                queue.append(prereq)

    # Step 2: Topological sort on necessary subgraph
    # Build indegree for necessary subgraph
    indegree_sub = [0] * (n + 1)
    for course in range(1, n + 1):
        if necessary[course]:
            for nxt in forward[course]:
                if necessary[nxt]:
                    indegree_sub[nxt] += 1

    # Kahn's algorithm
    q = deque()
    for course in range(1, n + 1):
        if necessary[course] and indegree_sub[course] == 0:
            q.append(course)

    order = []
    while q:
        course = q.popleft()
        order.append(course)
        for nxt in forward[course]:
            if necessary[nxt]:
                indegree_sub[nxt] -= 1
                if indegree_sub[nxt] == 0:
                    q.append(nxt)

    # Check if all necessary courses are in order (no cycle)
    if len(order) != sum(necessary):
        print(-1)
        return

    # Output
    print(len(order))
    print(' '.join(map(str, order)))

if __name__ == "__main__":
    main()

