                    sim_time = arrivals[j]
                sim_time += t
                if sim_time >= tf:
                    break

            # Check if Vasya can be served
            if sim_time < tf:
                # Vasya arrives at candidate
                if sim_time <= candidate:
                    wait_time = 0
                else:
                    wait_time = sim_time - candidate

                # Check if service can complete
                service_start = max(sim_time, candidate)
                if service_start + t <= tf:
