def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    ts = int(data[0])
    tf = int(data[1])
    t = int(data[2])
    n = int(data[3])

    arrivals = []
    if n > 0:
        arrivals = list(map(int, data[4:4+n]))

    # If no visitors, Vasya can come at ts
    if n == 0:
        print(ts)
        return

    # Group visitors by arrival time
    grouped_arrivals = []
    for time in arrivals:
        if not grouped_arrivals or grouped_arrivals[-1][0] != time:
            grouped_arrivals.append([time, 1])
        else:
            grouped_arrivals[-1][1] += 1

    best_time = ts
    best_wait = float('inf')

    # Check arrival at ts
    current_time = ts
    wait_time = 0
    if ts < arrivals[0]:
        wait_time = 0
    else:
        # Simulate queue from beginning
        current_time = ts
        for time, count in grouped_arrivals:
            if time <= current_time:
                current_time += count * t
            else:
                break
        wait_time = max(0, current_time - ts)

    if wait_time < best_wait and current_time + t <= tf:
        best_wait = wait_time
        best_time = ts

    # Check arrival just before each visitor
    current_time = ts
    for i in range(len(grouped_arrivals)):
        time, count = grouped_arrivals[i]

        # Candidate arrival: just before this group
        candidate = time - 1
        if candidate >= 0:
            # Simulate queue up to this candidate
            sim_time = ts
            for j in range(i):
                prev_time, prev_count = grouped_arrivals[j]
                if prev_time <= sim_time:
                    sim_time += prev_count * t
                else:
                    sim_time = prev_time + prev_count * t

            # Check if candidate arrives before current service completion
            if candidate >= sim_time:
                wait = 0
                serve_start = candidate
            else:
                wait = sim_time - candidate
                serve_start = sim_time

            # Check if service can complete
