import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    ts = int(data[0])
    tf = int(data[1])
    t = int(data[2])
    n = int(data[3])
    arrivals = list(map(int, data[4:4+n])) if n > 0 else []

    best_time = 0
    best_wait = float('inf')

    # Candidate: arrive at time 0
    current_time = ts
    if arrivals:
        first_arrival = arrivals[0]
        if first_arrival >= ts:
            wait = 0
        else:
            wait = ts - first_arrival
            current_time = first_arrival + t
    else:
        wait = 0
    if wait < best_wait and current_time + t <= tf:
        best_wait = wait
        best_time = 0

    # Candidates: arrive just before each visitor or at their exact time
    current_time = ts
    for i in range(n):
        time = arrivals[i]
        # Candidate: arrive at time-1 (if non-negative)
        if time-1 >= 0:
            cand = time-1
            # Simulate from start up to just before this visitor
            temp_time = ts
            for j in range(i):
                arr = arrivals[j]
                if arr > temp_time:
                    temp_time = arr
                temp_time += t
                if temp_time > tf:
                    break
            if cand >= temp_time:
                wait = 0
                serve_start = cand
            else:
                wait = temp_time - cand
                serve_start = temp_time
            if serve_start + t <= tf and wait < best_wait:
                best_wait = wait
                best_time = cand

        # Candidate: arrive exactly at visitor's time
        cand = time
        temp_time = ts
        for j in range(i):
            arr = arrivals[j]
            if arr > temp_time:
                temp_time = arr
            temp_time += t
            if temp_time > tf:
                break
        if cand >= temp_time:
            wait = 0
            serve_start = cand
        else:
            wait = temp_time - cand
            serve_start = temp_time
        if serve_start + t <= tf and wait < best_wait:
            best_wait = wait
            best_time = cand

        # Update current_time for next iteration
        if time > current_time:
            current_time = time
        current_time += t
        if current_time > tf:
            break

    # Candidate: arrive after all visitors
    current_time = ts
    for arr in arrivals:
        if arr > current_time:
            current_time = arr
        current_time += t
        if current_time > tf:
            break
    if current_time + t <= tf:
        cand = max(0, current_time)
        wait = 0
        if wait < best_wait:
            best_wait = wait
            best_time = cand

    # Candidate: arrive at ts if it's before first visitor
    if arrivals and ts < arrivals[0]:
        wait = 0
        if wait < best_wait:
            best_wait = wait
            best_time = ts

    print(best_time)

