import sys

def can_seat(groups, X, max_rows=float('inf')):
    """Check if all groups can be seated with width X using at most max_rows rows."""
    rows_used = 0
    remaining = groups[:]  # copy

    while any(r > 0 for r in remaining):
        # Try to fill current row
        row_seats = X
        # Prefer larger groups first to minimize fragmentation
        for size in range(len(remaining)-1, 0, -1):
            count = remaining[size-1]
            if count == 0:
                continue
            # Each group of size needs size seats plus 1 empty seat after (except at row end)
            seats_needed = size + 1
            while count > 0 and row_seats >= size:
                if row_seats >= seats_needed:
                    row_seats -= seats_needed
                elif row_seats == size:  # fits exactly at row end
                    row_seats -= size
                else:
                    break
                count -= 1
                remaining[size-1] -= 1
            remaining[size-1] = count
            if row_seats < min(r for r in remaining if r > 0):
                break
        rows_used += 1
        if rows_used > max_rows:
            return False
    return True

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    groups = list(map(int, data[1:1+n]))

    total_people = sum((i+1)*groups[i] for i in range(n))

    # Binary search on X from 1 to 12
    low, high = 1, 12
    answer = None

    while low <= high:
        mid = (low + high) // 2
        # Estimate max rows needed: worst case each group takes its own row
        max_rows_possible = sum(groups) + total_people  # generous upper bound
        if can_seat(groups, mid, max_rows_possible):
            answer = mid
            high = mid - 1
        else:
            low = mid + 1

    if answer is None:
        print("impossible")
    else:
        print(answer)

if __name__ == "__main__":
    solve()

