def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Sort the array
    a.sort()

    # Check for invalid initial conditions
    dup_count = 0
    dup_value = -1
    for i in range(1, n):
        if a[i] == a[i-1]:
            dup_count += 1
            dup_value = a[i]

    # If there are more than one duplicate pair, CSL wins immediately
    if dup_count > 1:
        print("cslnb")
        return

    # If there's exactly one duplicate pair
    if dup_count == 1:
        # Check if the duplicate value is 0 or if decreasing it would create another duplicate
        if dup_value == 0:
            print("cslnb")
            return
        # Check if there's a[i] = dup_value - 1
        for i in range(n):
            if a[i] == dup_value - 1:
                print("cslnb")
                return
        # Also check if there are more than 2 piles with the same value
        count_dup = 0
        for val in a:
            if val == dup_value:
                count_dup += 1
        if count_dup > 2:
            print("cslnb")
            return

    # Calculate total moves needed to reach [0, 1, 2, ..., n-1]
    total_moves = 0
    for i in range(n):
        if a[i] < i:
            print("cslnb")
            return
        total_moves += a[i] - i

    # If total_moves is odd, Tokitsukaze wins, otherwise CSL wins
    if total_moves % 2 == 1:
        print("sjfnb")
    else:
        print("cslnb")

