        'C:',
        'B: ----------------------------------------------------------',
        'A:',
        'g: ----------------------------------------------------------',
        'f:',
        'e: ----------------------------------------------------------',
        'd:',
        'c:',
        'b:',
        'a: ----------------------------------------------------------'
    ]

    # Map pitches to line indices (0-based from top)
    pitch_to_line = {
        'G': 0, 'F': 1, 'E': 2, 'D': 3, 'C': 4, 'B': 5, 'A': 6,
        'g': 7, 'f': 8, 'e': 9, 'd': 10, 'c': 11, 'b': 12, 'a': 13
    }

    # Initialize staff as list of lists of characters
    staff = []
    for line in staff_lines:
        if ':' in line:
            prefix, rest = line.split(':', 1)
            staff.append([prefix + ':'] + list(rest))
        else:
            staff.append([''] + list(line))

    # Process each note
    current_col = len(staff[0])  # Start after initial staff

    for note in notes:
        # Parse pitch and duration
        pitch_end = 1
        while pitch_end < len(note) and note[pitch_end].isdigit():
            pitch_end += 1
        pitch = note[:pitch_end]
        duration = int(note[pitch_end:]) if pitch_end < len(note) else 1

        line_idx = pitch_to_line[pitch]

        # Ensure staff is wide enough
        needed_cols = current_col + duration
        for row in staff:
            while len(row) < needed_cols:
                # Add appropriate character based on row type
                if row[0] in ['F:', 'D:', 'B:', 'g:', 'e:', 'a:']:
                    row.append('-')
                else:
                    row.append(' ')

        # Place asterisks for the note duration
        for offset in range(duration):
            col = current_col + offset
            # Replace character at this position with asterisk
            if staff[line_idx][col] == ' ' or staff[line_idx][col] == '-':
                staff[line_idx][col] = '*'
            else:
                # If there's already an asterisk (shouldn't happen), keep it
                pass

        # Move to next note position with separator
        current_col += duration + 1

        # Add separator column
        for row_idx, row in enumerate(staff):
            if len(row) < current_col:
                if row[0] in ['F:', 'D:', 'B:', 'g:', 'e:', 'a:']:
                    row.append('-')
                else:
                    row.append(' ')

    # Trim trailing empty columns (except separator after last note)
    # Find max column with content
    max_col = 0
    for row in staff:
        # Look for last non-space, non-dash character (excluding prefix)
        for col in range(len(row)-1, 0, -1):
            if row[col] != ' ' and row[col] != '-':
                max_col = max(max_col, col)
                break

    # Trim to max_col + 1 to keep separator after last note
    trim_to = max_col + 2  # +1 for separator, +1 for 0-based indexing
    for row in staff:
        if len(row) > trim_to:
            del row[trim_to:]

    # Output
    for row in staff:
        print(''.join(row))

