import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])
    prefs = list(map(int, data[2:2+n]))

    # Build graph: i -> prefs[i-1]
    adj = [[] for _ in range(n+1)]
    for i in range(1, n+1):
        adj[i].append(prefs[i-1])

    # Find strongly connected components (SCCs) using Kosaraju's algorithm
    visited = [False] * (n+1)
    order = []

    def dfs1(u):
        visited[u] = True
        for v in adj[u]:
            if not visited[v]:
                dfs1(v)
        order.append(u)

    for i in range(1, n+1):
        if not visited[i]:
            dfs1(i)

    # Transpose graph
    adjT = [[] for _ in range(n+1)]
    for u in range(1, n+1):
        for v in adj[u]:
            adjT[v].append(u)

    visited = [False] * (n+1)
    sccs = []

    def dfs2(u, comp):
        visited[u] = True
        comp.append(u)
        for v in adjT[u]:
            if not visited[v]:
                dfs2(v, comp)

    for u in reversed(order):
        if not visited[u]:
            comp = []
            dfs2(u, comp)
            sccs.append(comp)

    # Process SCCs
    comp_id = [0] * (n+1)
    for idx, comp in enumerate(sccs):
        for node in comp:
            comp_id[node] = idx

    # Build DAG of SCCs
    dag_size = len(sccs)
    dag_adj = [[] for _ in range(dag_size)]
    indeg = [0] * dag_size
    for u in range(1, n+1):
        for v in adj[u]:
            cu = comp_id[u]
            cv = comp_id[v]
            if cu != cv:
                dag_adj[cu].append(cv)
                indeg[cv] += 1

    # Topological order
    topo = []
    from collections import deque
    q = deque([i for i in range(dag_size) if indeg[i] == 0])
    while q:
        u = q.popleft()
        topo.append(u)
        for v in dag_adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)

    # DP on DAG: dp[i] = max participants from component i and its successors
    comp_sizes = [len(comp) for comp in sccs]
    dp = [0] * dag_size
    for u in reversed(topo):
        best = comp_sizes[u]
        for v in dag_adj[u]:
            best = max(best, comp_sizes[u] + dp[v])
        dp[u] = best

    # Find answer: we can take any subset of components respecting dependencies
    # Since we want max participants ≤ k, we try all combinations via knapsack
    # But n ≤ 1000, so we can do DP on number of participants
    max_possible = min(sum(comp_sizes), k)
    possible = [False] * (max_possible + 1)
    possible[0] = True

    for u in topo:
        size = comp_sizes[u]
        # We must take all nodes in this SCC if we take any
        new_possible = possible[:]
        for w in range(max_possible - size, -1, -1):
            if possible[w]:
                new_possible[w + size] = True
        possible = new_possible

    # Find largest achievable ≤ k
    ans = 0
    for w in range(k, -1, -1):
        if possible[w]:
            ans = w
            break

    print(ans)

