    elif c == 'J':
        return 11  # wildcard
    elif c == 'Q':
        return 12
    elif c == 'K':
        return 13
    else:
        return int(c)

def simulate_game(deck):
    """Simulate the game and return True if Theta wins, False otherwise."""
    # Deal initial cards
    theta_slots = [deck[i] for i in range(10)]  # face-down cards
    friend_slots = [deck[i] for i in range(10, 20)]

    # Track filled slots: 0 = unfilled, 1 = filled
    theta_filled = [0] * 10
    friend_filled = [0] * 10

    # Discard pile (cards that couldn't be placed)
    discard = []

    # Drawing pile starts from index 20
    draw_index = 20

    # Whose turn? True = Theta, False = friend
    theta_turn = True

    # Game loop
    while True:
        # Check if someone has won
        if all(theta_filled):
            return True
        if all(friend_filled):
            return False

        # Get current player's state
        if theta_turn:
            filled = theta_filled
            slots = theta_slots
            is_theta = True
        else:
            filled = friend_filled
            slots = friend_slots
            is_theta = False

        # Player's turn
        turn_active = True
        current_card = None

        while turn_active:
            # Draw or use uncovered card
            if current_card is None:
                if draw_index >= 52:
                    # Should not happen per problem guarantee
                    break
                current_card = deck[draw_index]
                draw_index += 1

            card_val = card_value(current_card)

            # Check if card is usable
            if card_val == 11:  # Jack (wildcard)
                # Find optimal slot for Jack
                if is_theta:
                    # Theta's strategy: minimize chance of being left with unfilled slot
                    # We need to consider which cards are already placed or discarded
                    placed_or_discarded = set()
                    # Add cards in filled slots
                    for i in range(10):
                        if filled[i]:
                            placed_or_discarded.add(card_value(slots[i]))
                    # Add cards in discard pile
                    for c in discard:
                        placed_or_discarded.add(card_value(c))

                    # Find unfilled slots where the corresponding card is still available
                    # (not placed or discarded)
                    available_slots = []
                    for i in range(10):
                        if not filled[i]:
                            slot_needs = i + 1  # Slot 0 needs Ace/1, slot 1 needs 2, etc.
                            if slot_needs not in placed_or_discarded:
                                available_slots.append(i)

                    if available_slots:
                        # Place Jack in lowest-numbered available slot
                        slot_to_fill = min(available_slots)
                    else:
                        # All needed cards are already placed or discarded
                        # Use simple strategy as fallback
                        slot_to_fill = min(i for i in range(10) if not filled[i])
                else:
                    # Friend's strategy: always fill lowest-numbered unfilled slot
                    slot_to_fill = min(i for i in range(10) if not filled[i])

                # Fill the slot
                filled[slot_to_fill] = 1
                # The uncovered card becomes the new current card
                current_card = slots[slot_to_fill]

            elif 1 <= card_val <= 10:
