                    discard.append(current_card)
                    turn_active = False
            else:
                # Queen or King, discard and end turn
                discard.append(current_card)
                turn_active = False

            # Check if player filled all slots
            if all(filled):
                return is_theta

            # If we just discarded, turn ends
            if not turn_active:
                break

        # Switch turns
        theta_turn = not theta_turn

