def is_tolerable(s, p):
    """Check if string s is tolerable given p letters."""
    n = len(s)
    # Check each contiguous substring of length 2 or more
    for length in range(2, n + 1):
        for start in range(n - length + 1):
            sub = s[start:start + length]
            if sub == sub[::-1]:
                return False
    # Check characters are within first p letters
    max_char = chr(ord('a') + p - 1)
    for ch in s:
        if ch > max_char:
            return False
    return True

def next_tolerable(s, p):
    """Find lexicographically next tolerable string or return None."""
    n = len(s)
    max_char = chr(ord('a') + p - 1)

    # Convert to list for easy modification
    s_list = list(s)

    # Try to increment from the end
    for i in range(n - 1, -1, -1):
        original_char = s_list[i]
        # Try all possible next characters at position i
        for ch_code in range(ord(original_char) + 1, ord(max_char) + 1):
            s_list[i] = chr(ch_code)
            # Check if this prefix could lead to a tolerable string
            # We only need to check palindromes involving the changed position
            tolerable = True
            # Check all substrings ending at or after position i
            for length in range(2, n + 1):
                for start in range(max(0, i - length + 1), min(i, n - length) + 1):
                    end = start + length - 1
                    if end >= i:  # Substring includes changed position
                        sub = ''.join(s_list[start:end + 1])
                        if sub == sub[::-1]:
                            tolerable = False
                            break
                if not tolerable:
                    break
            if not tolerable:
                continue

            # Fill the rest with smallest possible characters
            for j in range(i + 1, n):
                # Try 'a' first, then 'b', etc.
                for ch_code2 in range(ord('a'), ord(max_char) + 1):
                    s_list[j] = chr(ch_code2)
                    # Check if this character creates a palindrome
                    ok = True
                    # Check all substrings ending at j
                    for length in range(2, n + 1):
                        for start in range(max(0, j - length + 1), min(j, n - length) + 1):
                            end = start + length - 1
                            if end == j:  # Substring ends at current position
                                sub = ''.join(s_list[start:end + 1])
                                if sub == sub[::-1]:
                                    ok = False
                                    break
                        if not ok:
                            break
                    if ok:
                        break
                else:
                    # No valid character found for this position
                    tolerable = False
                    break

            if tolerable:
                return ''.join(s_list)

        # Reset this position to original and continue with previous position
        s_list[i] = original_char

    return None

