import sys

def read_board():
    """Read the ASCII chessboard from stdin."""
    lines = []
    for line in sys.stdin:
        line = line.rstrip('\n')
        if line:
            lines.append(line)
    return lines

def parse_board(lines):
    """Extract piece positions from the ASCII board."""
    white_pieces = []
    black_pieces = []

    # The board has 8 rows, each represented by 3 lines in the ASCII art
    # The actual piece row is the middle line of each 3-line block
    for row_idx in range(8):
        # Calculate which line contains the pieces for this row
        # First line is border, second line has pieces, third line is border
        piece_line_idx = 1 + row_idx * 3
        if piece_line_idx >= len(lines):
            break

        piece_line = lines[piece_line_idx]

        # Each cell is 4 characters wide: '|', content (3 chars), then next '|' or end
        for col_idx in range(8):
            # Position in the line where the piece character would be
            # The piece is at the 2nd character of each 4-character cell
            char_pos = 2 + col_idx * 4
            if char_pos < len(piece_line):
                ch = piece_line[char_pos]
                if ch != '.' and ch != ':':
                    # Convert to chess notation
                    col_letter = chr(ord('a') + col_idx)
                    row_number = 8 - row_idx  # Row 8 is top in input
                    pos = f"{col_letter}{row_number}"

                    if ch.isupper():
                        # White piece
                        piece_type = ch
                        white_pieces.append((piece_type, pos, row_number, col_letter))
                    else:
                        # Black piece
                        piece_type = ch.upper()
                        black_pieces.append((piece_type, pos, row_number, col_letter))

    return white_pieces, black_pieces

def sort_pieces(pieces, is_white):
    """Sort pieces according to the problem requirements."""
    # Order: K, Q, R, B, N, P
    type_order = {'K': 0, 'Q': 1, 'R': 2, 'B': 3, 'N': 4, 'P': 5}

    def sort_key(piece):
        piece_type, pos, row, col = piece
        # Primary: type order
        # Secondary: for white, smaller row first; for black, larger row first
        # Tertiary: for same row, smaller column first
        if is_white:
            row_key = row
        else:
            row_key = -row  # Negative for descending order

        return (type_order[piece_type], row_key, col)

    return sorted(pieces, key=sort_key)

def format_output(white_pieces, black_pieces):
    """Format the output as specified."""
    def format_piece_list(pieces):
        result = []
        for piece_type, pos, _, _ in pieces:
            if piece_type == 'P':
                # Pawns don't get a letter prefix
                result.append(pos)
            else:
                result.append(f"{piece_type}{pos}")
        return ','.join(result)

    white_str = format_piece_list(white_pieces)
    black_str = format_piece_list(black_pieces)

    return f"White: {white_str}\nBlack: {black_str}"

def main():
    lines = read_board()
    white_pieces, black_pieces = parse_board(lines)

    white_sorted = sort_pieces(white_pieces, is_white=True)
    black_sorted = sort_pieces(black_pieces, is_white=False)

    output = format_output(white_sorted, black_sorted)
    print(output)

if __name__ == "__main__":
    main()

