def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    N = int(data[idx]); idx += 1
    V = [0] + list(map(int, data[idx:idx+N])); idx += N

    adj = [[] for _ in range(N+1)]
    parent = [0]*(N+1)
    for _ in range(N-1):
        a = int(data[idx]); b = int(data[idx+1]); idx += 2
        adj[a].append(b)
        parent[b] = a

    # DFS to compute subtree joke sets
    subtree_jokes = [set() for _ in range(N+1)]

    def dfs(u):
        s = {V[u]}
        for v in adj[u]:
            child_set = dfs(v)
            s.update(child_set)
        subtree_jokes[u] = s
        return s

    dfs(1)

    # Check if a set of jokes is consecutive
    def is_consecutive(jokes_set):
        if not jokes_set:
            return True
        lst = sorted(jokes_set)
        for i in range(1, len(lst)):
            if lst[i] != lst[i-1] + 1:
                return False
        return True

    # DP on tree: dp[u] = number of valid joke sets in subtree rooted at u
    # where u is invited and all constraints are satisfied
    dp = [0]*(N+1)

    def dfs_dp(u):
        # Base: leaf node
        if not adj[u]:
            dp[u] = 1  # only {V[u]}
            return

        # Process children first
        for v in adj[u]:
            dfs_dp(v)

        # For node u to be invited, all its children must be invited
        # and the set of jokes in its subtree (including u) must be consecutive
        if is_consecutive(subtree_jokes[u]):
            # All children must be invited, so multiply their dp values
            ways = 1
            for v in adj[u]:
                ways *= dp[v]
            dp[u] = ways
        else:
            dp[u] = 0

    dfs_dp(1)

    # Total answer is dp[1] (since Petar (node 1) must be invited)
    print(dp[1])

if __name__ == "__main__":
    solve()

