def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    m, n, t = map(int, data)

    # Define operations based on t
    if t == 1:
        # O(n!)
        # Compute n! iteratively to avoid recursion depth issues
        ops = 1
        for i in range(2, n + 1):
            ops *= i
            if ops > m:
                print("TLE")
                return
        print("AC" if ops <= m else "TLE")
    elif t == 2:
        # O(2^n)
        # Compute 2^n using bit shift
        if n >= 31:  # 2^31 > 2e9, so definitely > m for m <= 1e9
            print("TLE")
        else:
            ops = 1 << n  # 2^n
            print("AC" if ops <= m else "TLE")
    elif t == 3:
        # O(n^4)
        ops = n ** 4
        print("AC" if ops <= m else "TLE")
    elif t == 4:
        # O(n^3)
        ops = n ** 3
        print("AC" if ops <= m else "TLE")
    elif t == 5:
        # O(n^2)
        ops = n * n
        print("AC" if ops <= m else "TLE")
    elif t == 6:
        # O(n log n)
        # Use floating point for log2, compare directly
        if n <= 1:
            # For n=0 or 1, log is 0 or undefined, but operation count is small
            print("AC" if n <= m else "TLE")
        else:
            # Compare n * log2(n) <= m using floating point
            if n * math.log2(n) <= m:
                print("AC")
            else:
                print("TLE")
    elif t == 7:
        # O(n)
        ops = n
        print("AC" if ops <= m else "TLE")
    else:
        # Invalid t, but problem guarantees t in [1..7]
        print("TLE")

