def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    bananas = list(map(int, data[1:1+n]))

    # Prefix sums for quick range sum queries
    prefix = [0] * (n + 1)
    for i in range(1, n + 1):
        prefix[i] = prefix[i-1] + bananas[i-1]

    # dp[i] = maximum number of executives using first i briefcases
    dp = [0] * (n + 1)
    # last_sum[i] = total bananas for last executive when using first i briefcases optimally
    last_sum = [0] * (n + 1)

    for i in range(1, n + 1):
        # Try to start a new executive at position j (1-indexed)
        for j in range(1, i + 1):
            # Sum from j to i
            current_sum = prefix[i] - prefix[j-1]
            # Check if we can append this as a new executive after using first j-1 briefcases
            if dp[j-1] > 0:
                # Need non-decreasing condition
                if current_sum >= last_sum[j-1]:
                    if dp[j-1] + 1 > dp[i]:
                        dp[i] = dp[j-1] + 1
                        last_sum[i] = current_sum
            else:
                # First executive
                if dp[i] < 1:
                    dp[i] = 1
                    last_sum[i] = current_sum

    print(dp[n])

