                if 0 <= ni < n and 0 <= nj < m and field[ni][nj] == '*':
                    bomb_count += 1

            if field[i][j] == '.':
                # Empty cell: must have 0 neighboring bombs
                if bomb_count != 0:
                    return "NO"
            else:
                # Digit cell: must match bomb count
                expected = int(field[i][j])
                if bomb_count != expected:
                    return "NO"

    return "YES"


