MOD = 998244353

def cross(ax, ay, bx, by):
    return ax * by - ay * bx

def orientation(a, b, c):
    return cross(b[0]-a[0], b[1]-a[1], c[0]-a[0], c[1]-a[1])

def is_convex(poly):
    if len(poly) < 3:
        return False
    n = len(poly)
    prev = 0
    for i in range(n):
        a, b, c = poly[i], poly[(i+1)%n], poly[(i+2)%n]
        cur = orientation(a, b, c)
        if cur == 0:
            return False
        if prev != 0 and cur * prev < 0:
            return False
        prev = cur
    return True

def points_in_convex_hull(points, hull):
    if len(hull) < 3:
        return len(hull)
    count = 0
    for p in points:
        inside = True
        n = len(hull)
        for i in range(n):
            a, b = hull[i], hull[(i+1)%n]
            if orientation(a, b, p) < 0:
                inside = False
                break
        if inside:
            count += 1
    return count

