import math
MOD = 998244353

def cross(o, a, b):
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def convex_hull(points):
    points = sorted(points)
    lower = []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    return lower[:-1] + upper[:-1]

def point_in_polygon(p, poly):
    wn = 0
    n = len(poly)
    for i in range(n):
        j = (i + 1) % n
        if poly[i][1] <= p[1]:
            if poly[j][1] > p[1] and cross(poly[i], poly[j], p) > 0:
                wn += 1
        else:
            if poly[j][1] <= p[1] and cross(poly[i], poly[j], p) < 0:
                wn -= 1
    return wn != 0

def main():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    it = iter(input_data)
    N = int(next(it))
    points = [(int(next(it)), int(next(it))) for _ in range(N)]

    # Precompute all subsets and their convex hulls
    total = 0
    for mask in range(1, 1 << N):
        subset = [points[i] for i in range(N) if mask & (1 << i)]
        if len(subset) < 3:
            continue
        hull = convex_hull(subset)
        # Check if subset equals hull vertices (no interior subset points)
        if len(hull) != len(subset):
            continue
        # Verify hull vertices match subset (order might differ)
        hull_set = set(hull)
        subset_set = set(subset)
        if hull_set != subset_set:
            continue
        # Count points inside/on hull
        n_inside = 0
        for p in points:
            if p in hull_set:
                n_inside += 1
            elif point_in_polygon(p, hull):
                n_inside += 1
        # Score = 2^(N - n_inside)
        exponent = N - n_inside
        score = pow(2, exponent, MOD)
        total = (total + score) % MOD
    print(total)

