    pairs_L1 = []  # (sum, i, j) where i<j
    pairs_L2 = []  # (sum, i, j) where i<j

    # Two-pointer to find all pairs with sum <= L1 or L2
    for i in range(N):
        j = N-1
        while j > i and tubes[i] + tubes[j] > L1:
            j -= 1
        while j > i:
            pairs_L1.append((tubes[i] + tubes[j], i, j))
            j -= 1

    for i in range(N):
        j = N-1
        while j > i and tubes[i] + tubes[j] > L2:
            j -= 1
        while j > i:
            pairs_L2.append((tubes[i] + tubes[j], i, j))
            j -= 1

    if not pairs_L1 or not pairs_L2:
        print("Impossible")
        return

    # Step 2: Sort pairs by sum descending
    pairs_L1.sort(key=lambda x: -x[0])
    pairs_L2.sort(key=lambda x: -x[0])

