import math

def orientation(p, q, r):
    """Return positive if p-q-r is clockwise, negative if counterclockwise, 0 if collinear."""
    val = (q[1] - p[1]) * (r[0] - q[0]) - (q[0] - p[0]) * (r[1] - q[1])
    if val > 0:
        return 1
    elif val < 0:
        return -1
    return 0

def on_segment(p, q, r):
    """Check if point q lies on segment pr."""
    return (min(p[0], r[0]) <= q[0] <= max(p[0], r[0]) and
            min(p[1], r[1]) <= q[1] <= max(p[1], r[1]))

def point_in_polygon(point, polygon):
    """Ray casting algorithm for point in polygon (including boundary)."""
    x, y = point
    n = len(polygon)
    inside = False
    for i in range(n):
        x1, y1 = polygon[i]
        x2, y2 = polygon[(i + 1) % n]
        # Check if point is on edge
        if orientation((x1, y1), (x2, y2), (x, y)) == 0 and on_segment((x1, y1), (x, y), (x2, y2)):
            return True
        # Ray casting logic
        if ((y1 > y) != (y2 > y)) and (x < (x2 - x1) * (y - y1) / (y2 - y1) + x1):
            inside = not inside
    return inside

def convex_hull(points):
    """Andrew's monotone chain algorithm for convex hull."""
    points = sorted(set(points))
    if len(points) <= 1:
        return points

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    lower = []
