def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    k = int(next(it))
    m = int(next(it))
    a = int(next(it))
    votes = [0] * (n + 1)
    last_vote = [0] * (n + 1)  # last vote time (1-indexed), 0 means no votes

    for time in range(1, a + 1):
        g = int(next(it))
        votes[g] += 1
        last_vote[g] = time

    remaining = m - a
    result = [0] * (n + 1)

    for i in range(1, n + 1):
        # Check if candidate i can be guaranteed to win
        # Best case for i: give all remaining votes to i
        best_votes_i = votes[i] + remaining
        best_last_i = last_vote[i] if votes[i] > 0 else m  # if no votes yet, last vote at end
        if votes[i] == 0:
            best_last_i = m  # if no votes, last vote at the very end

        # Count how many candidates are definitely better than i in this scenario
        better_count = 0
        for j in range(1, n + 1):
            if j == i:
                continue
            if votes[j] > best_votes_i:
                better_count += 1
            elif votes[j] == best_votes_i:
                # Tie: compare last vote times
                if votes[j] == 0:
                    # Both have 0 votes, but i got all remaining, so j has 0 votes with last vote 0
                    # j ranks lower because last_vote[j] = 0 < best_last_i
                    pass
                else:
                    if last_vote[j] < best_last_i:
                        better_count += 1
        if better_count < k:
            # i can be in top-k in best case
            # Now check worst case: can i still be in top-k?
            # Worst case for i: give votes to others to push i down
            worst_votes_i = votes[i]
            worst_last_i = last_vote[i]

            # Distribute remaining votes to other candidates to minimize i's rank
            # We want to make as many candidates as possible beat or tie with i
            votes_copy = votes[:]
            last_copy = last_vote[:]

            # First, give votes to candidates with 0 votes to make them beat i if possible
            # But only if they can get more votes than i or tie with later last vote
            rem = remaining
            for j in range(1, n + 1):
                if j == i:
                    continue
                if votes_copy[j] == 0 and rem > 0:
                    # Give one vote to make them have 1 vote
                    votes_copy[j] += 1
                    last_copy[j] = m  # last vote at the end
                    rem -= 1

            # Then distribute remaining votes to make others beat i
            # Sort candidates by how close they are to beating i
            candidates = []
            for j in range(1, n + 1):
                if j == i:
                    continue
                # Calculate votes needed to beat i
                needed = max(0, worst_votes_i - votes_copy[j] + 1)
                # If tied, we need to make last vote earlier than i's
                if needed == 0 and votes_copy[j] == worst_votes_i:
                    if last_copy[j] > worst_last_i:
                        needed = 1  # need one more vote to break tie in i's favor
                candidates.append((needed, j))

            candidates.sort()  # sort by needed votes

            for needed, j in candidates:
                if rem >= needed:
                    votes_copy[j] += needed
                    if needed > 0:
                        last_copy[j] = m  # last vote at the end
                    rem -= needed
                else:
                    break

            # Now count how many candidates are better than i
            worse_count = 0
            for j in range(1, n + 1):
                if j == i:
                    continue
                if votes_copy[j] > worst_votes_i:
                    worse_count += 1
                elif votes_copy[j] == worst_votes_i:
                    if votes_copy[j] == 0:
                        # Both have 0 votes
                        if last_copy[j] < worst_last_i:
                            worse_count += 1
                    else:
                        if last_copy[j] < worst_last_i:
                            worse_count += 1

            if worse_count < k:
                # In worst case, i is still in top-k
                result[i] = 1
            else:
                result[i] = 2
        else:
            # i cannot be in top-k even in best case
