    # Count frequencies of each mass
    freq = {}
    for mass in a:
        freq[mass] = freq.get(mass, 0) + 1

    # For each possible k (1 to n), try to find a target sum m
    # such that there's exactly one subset of size k with sum m
    best = 0

    # Precompute all subset sums by size
    # Since n <= 100 and a_i <= 100, we can use DP
    max_sum = sum(a)

    # dp[k][s] = number of subsets of size k with sum s
    dp = [[0]*(max_sum+1) for _ in range(n+1)]
    dp[0][0] = 1

    for mass in a:
        # Update DP backwards to avoid reuse
        for k in range(n, 0, -1):
            for s in range(max_sum, mass-1, -1):
                if dp[k-1][s-mass]:
                    dp[k][s] += dp[k-1][s-mass]

    # For each mass value, check if we can uniquely identify some weights
    for mass, count in freq.items():
        # Try to ask for k = count weights with sum = mass*count
        k = count
        target_sum = mass * count
        if dp[k][target_sum] == 1:
            # All weights of this mass can be uniquely identified
            best = max(best, count)

        # Also check if we can identify some weights by asking for
        # a subset that contains exactly one weight of this mass
        # and some other weights uniquely
        for other_k in range(1, n+1):
            for other_sum in range(1, max_sum+1):
                if dp[other_k][other_sum] == 1:
                    # Check if this subset contains exactly one weight of mass 'mass'
                    # We need to count how many subsets of size other_k with sum other_sum
                    # contain exactly one weight of mass 'mass'
                    # We can compute this by DP with constraint

                    # DP for subsets containing exactly one weight of mass 'mass'
                    dp_constrained = [[0]*(max_sum+1) for _ in range(n+1)]
                    dp_constrained[0][0] = 1

                    for m_val in a:
                        for kk in range(n, 0, -1):
                            for ss in range(max_sum, m_val-1, -1):
                                if dp_constrained[kk-1][ss-m_val]:
                                    dp_constrained[kk][ss] += dp_constrained[kk-1][ss-m_val]

                    # Now subtract subsets with 0 or >1 of mass 'mass'
                    # Subsets with 0 of mass 'mass': remove all weights of mass 'mass' from consideration
                    dp_no_mass = [[0]*(max_sum+1) for _ in range(n+1)]
