    conditions = [[] for _ in range(N + 2)]
    for _ in range(M):
        l = int(next(it))
        r = int(next(it))
        x = int(next(it))
        conditions[l].append((r, x))

    # dp[a][b] where a <= b <= pos, pos is implicit current position
    # a, b are the two most recent distinct color positions (0 if not exist)
    # Initialize with pos = 0
    dp = [[0] * (N + 2) for _ in range(N + 2)]
    dp[0][0] = 1  # no colors placed yet

    for pos in range(1, N + 1):
        new_dp = [[0] * (N + 2) for _ in range(N + 2)]

        for a in range(0, pos):
            for b in range(a, pos):
                val = dp[a][b]
                if val == 0:
                    continue

                # Option 1: use same color as position a (if a > 0)
                if a > 0:
                    new_a, new_b = a, b
                    if new_a > new_b:
                        new_a, new_b = new_b, new_a
                    new_dp[new_a][new_b] = (new_dp[new_a][new_b] + val) % MOD

                # Option 2: use same color as position b (if b > 0)
