                new_dp[new_a][new_b] = (new_dp[new_a][new_b] + val) % MOD

        # Filter states that violate conditions ending at pos
        for a in range(0, pos + 1):
            for b in range(a, pos + 1):
                if new_dp[a][b] == 0:
                    continue

                valid = True
                # Check all conditions with l <= pos <= r
                for l in range(1, pos + 1):
                    for r, x in conditions[l]:
                        if r < pos:
                            continue
                        # Count distinct colors in [l, pos]
                        cnt = 0
                        if a >= l:
                            cnt += 1
                        if b >= l and b != a:
                            cnt += 1
                        if pos >= l and pos != a and pos != b:
                            cnt += 1
                        if cnt != x:
                            valid = False
                            break
                    if not valid:
                        break

                if not valid:
                    new_dp[a][b] = 0

        dp = new_dp

    # Sum all valid states after placing all N squares
    ans = 0
    for a in range(0, N + 1):
        for b in range(a, N + 1):
            ans = (ans + dp[a][b]) % MOD
    return ans

