    if not data:
        return
    it = iter(data)
    n = int(next(it))
    c = int(next(it))

    # Initialize adjacency matrix with 2008 (default year for unknown pairs)
    INF = 2008
    adj = [[INF] * n for _ in range(n)]
    for i in range(n):
        adj[i][i] = 0

    # Read known encounters
    for _ in range(c):
        a = int(next(it)) - 1
        b = int(next(it)) - 1
        y = int(next(it))
        adj[a][b] = adj[b][a] = y

    # Floyd-Warshall to find earliest meeting year for all pairs
    for k in range(n):
        for i in range(n):
            if adj[i][k] == INF:
                continue
            for j in range(n):
                if adj[k][j] == INF:
                    continue
                adj[i][j] = min(adj[i][j], max(adj[i][k], adj[k][j]))

    # Collect all distinct years from the matrix (including 2008)
    years_set = set()
    for i in range(n):
        for j in range(i+1, n):
            years_set.add(adj[i][j])
    years = sorted(years_set)

    # Try each candidate year Y
    max_size = (2 * n) // 3  # floor of 2n/3
    best_year = None

    for Y in years:
        # Build graph where edge exists if pair met before Y
        # We'll use BFS to find connected components
        visited = [False] * n
        components = []

        for i in range(n):
            if not visited[i]:
                # Start new component
                stack = [i]
                comp = []
                while stack:
                    u = stack.pop()
