                components.append(comp)

        # Check if we can partition into two groups with size constraints
        # Each component must be entirely in one group (before Y or after Y)
        # This becomes a subset sum problem: can we select some components to be in group1
        # such that size1 <= max_size and size2 = n - size1 <= max_size

        comp_sizes = [len(comp) for comp in components]
        total = n

        # Dynamic programming for subset sum
        dp = [False] * (max_size + 1)
        dp[0] = True

        for size in comp_sizes:
