def can_pair_with_max_distance(students, tutors, max_dist):
    """Check if a perfect bipartite matching exists with all distances <= max_dist."""
    n = len(students)
    # Build adjacency list: student i can be matched with tutor j if distance <= max_dist
    adj = [[] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if manhattan_distance(students[i], tutors[j]) <= max_dist:
                adj[i].append(j)

    # Hopcroft-Karp for bipartite matching
    pair_u = [-1] * n  # match for students
    pair_v = [-1] * n  # match for tutors
    dist = [0] * n

    from collections import deque

    def bfs():
        q = deque()
        for u in range(n):
            if pair_u[u] == -1:
                dist[u] = 0
                q.append(u)
            else:
                dist[u] = float('inf')
        found = False
        while q:
            u = q.popleft()
            for v in adj[u]:
                pu = pair_v[v]
                if pu == -1:
                    found = True
                elif dist[pu] == float('inf'):
                    dist[pu] = dist[u] + 1
                    q.append(pu)
        return found

    def dfs(u):
        for v in adj[u]:
            pu = pair_v[v]
            if pu == -1 or (dist[pu] == dist[u] + 1 and dfs(pu)):
                pair_u[u] = v
                pair_v[v] = u
                return True
        dist[u] = float('inf')
        return False

    matching = 0
    while bfs():
        for u in range(n):
            if pair_u[u] == -1 and dfs(u):
                matching += 1
    return matching == n

