def solve():
    input = sys.stdin.read().split()
    it = iter(input)
    N = int(next(it))
    C = int(next(it))

    # Read D matrix
    D = [[0] * (C + 1) for _ in range(C + 1)]
    for i in range(1, C + 1):
        for j in range(1, C + 1):
            D[i][j] = int(next(it))

    # Read initial colors
    init = [[0] * (N + 1) for _ in range(N + 1)]
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            init[i][j] = int(next(it))

    # Count how many squares of each initial color are in each modulo-3 group
    # group 0: (i+j) % 3 == 0
    # group 1: (i+j) % 3 == 1
    # group 2: (i+j) % 3 == 2
    cnt = [[0] * (C + 1) for _ in range(3)]
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            group = (i + j) % 3
            color = init[i][j]
            cnt[group][color] += 1

    # For each group, compute the total wrongness if we paint all squares in that group to color k
    # wrongness[group][k] = sum_{original_color=1..C} cnt[group][original_color] * D[original_color][k]
    wrongness = [[0] * (C + 1) for _ in range(3)]
    for g in range(3):
        for k in range(1, C + 1):
            total = 0
            for orig in range(1, C + 1):
                total += cnt[g][orig] * D[orig][k]
            wrongness[g][k] = total

    # We need to assign a distinct color to each group (since condition requires different colors for different groups)
    # Find the minimum sum of wrongness[0][a] + wrongness[1][b] + wrongness[2][c] where a, b, c are all distinct
    ans = float('inf')
    for a in range(1, C + 1):
        for b in range(1, C + 1):
            if a == b:
                continue
            for c in range(1, C + 1):
