    suffix = list(range(n))
    rank = [ord(c) for c in s]
    tmp = [0] * n
    k = 1
    while k < n:
        suffix.sort(key=lambda x: (rank[x], rank[x + k] if x + k < n else -1))
        tmp[suffix[0]] = 0
        for i in range(1, n):
            prev, cur = suffix[i - 1], suffix[i]
            tmp[cur] = tmp[prev] + ((rank[prev], rank[prev + k] if prev + k < n else -1) < (rank[cur], rank[cur + k] if cur + k < n else -1))
        rank, tmp = tmp, rank
        if rank[suffix[-1]] == n - 1:
            break
        k <<= 1
    return suffix

def build_lcp(s, suffix):
    n = len(s)
    rank = [0] * n
    for i, idx in enumerate(suffix):
        rank[idx] = i
    lcp = [0] * (n - 1)
    h = 0
    for i in range(n):
        if rank[i] > 0:
            j = suffix[rank[i] - 1]
            while i + h < n and j + h < n and s[i + h] == s[j + h]:
                h += 1
            lcp[rank[i] - 1] = h
            if h > 0:
                h -= 1
    return lcp

def build_rmq(arr):
    n = len(arr)
    log = [0] * (n + 1)
    for i in range(2, n + 1):
        log[i] = log[i // 2] + 1
    k = log[n] + 1
    st = [[0] * n for _ in range(k)]
