        while i + (1 << j) - 1 < n:
            st[j][i] = min(st[j - 1][i], st[j - 1][i + (1 << (j - 1))])
            i += 1
        j += 1
    return st, log

def query_rmq(st, log, l, r):
    if l > r:
        l, r = r, l
    j = log[r - l + 1]
    return min(st[j][l], st[j][r - (1 << j) + 1])

