    # Check if the sorted numbers already form an arithmetic progression
    # with equal differences between consecutive pairs
    if y - x == z - y:
        # The progression is increasing, so the fourth number is z + (y - x)
        return z + (y - x)
    else:
        # The missing number is between x and z, making the progression
        # The common difference d must satisfy: x, x+d, x+2d, x+3d
        # Since we have three numbers, one of them is at position 0, 1, 2, or 3
        # Try placing the missing number at each position and check consistency

