        # If missing number is at position 1, then x, m, y, z
        # Then d = m - x = y - m = z - y
        # From m - x = y - m, we get 2m = x + y, so m = (x + y)/2
        # And we need to check if y - m = z - y
        m = (x + y) / 2
        if m.is_integer() and y - m == z - y:
