        # Case 3: missing number is largest (position 3)
        # Then progression: x, y, z, m with common difference d = y - x = z - y
        if y - x == z - y:
            return z + (y - x)

        # If none of the above worked (shouldn't happen per problem statement),
        # return the most likely candidate
