    if not data:
        return
    n = int(data[0])
    cards = data[1:1+n]

    suits = {'s': [], 'h': [], 'd': [], 'c': []}
    for card in cards:
        suits[card[1]].append((rank_to_value(card[0]), card))

    # Sort each suit's cards by rank for both ascending and descending orders
    for suit in suits:
        suits[suit].sort(key=lambda x: x[0])  # ascending

    # Build all possible sorted sequences
    sorted_sequences = []
    suit_order = ['s', 'h', 'd', 'c']

    # Generate all combinations of suit orders (4! = 24)
    from itertools import permutations
    for perm in permutations(suit_order):
        # For each suit, choose ascending or descending
        for mask in range(16):  # 2^4 possibilities
            seq = []
            for i, suit in enumerate(perm):
                cards_in_suit = suits[suit]
                if not cards_in_suit:
                    continue
                if (mask >> i) & 1:  # descending
                    seq.extend([card[1] for card in reversed(cards_in_suit)])
                else:  # ascending
                    seq.extend([card[1] for card in cards_in_suit])
            sorted_sequences.append(seq)

