import math

MOD = 10**9 + 7

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    nums = list(map(int, data[1:1+n]))

    # Special case for n=2
    if n == 2:
        print(1 if math.gcd(nums[0], nums[1]) > 1 else 0)
        return

    # Precompute GCD matrix
    gcd_mat = [[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(i+1, n):
            g = math.gcd(nums[i], nums[j])
            gcd_mat[i][j] = g
            gcd_mat[j][i] = g

    # DP table: dp[l][r] = number of ways to triangulate polygon from l to r
    dp = [[0]*n for _ in range(n)]

    # Initialize for triangles
    for l in range(n):
        for r in range(l+2, n):
            if gcd_mat[l][r] > 1:
                dp[l][r] = 1

    # DP for larger polygons
    for length in range(4, n+1):  # length of polygon segment
        for l in range(n):
            r = (l + length - 1) % n
            if gcd_mat[l][r] <= 1:
                continue

            total = 0
            # Choose middle vertex m between l and r
            for m in range(l+1, r):
                if gcd_mat[l][m] > 1 and gcd_mat[m][r] > 1:
                    left_ways = dp[l][m]
                    right_ways = dp[m][r]
                    total = (total + left_ways * right_ways) % MOD

            dp[l][r] = (dp[l][r] + total) % MOD

    # Sum over all possible root edges
    result = 0
    for m in range(1, n-1):
        if gcd_mat[0][m] > 1 and gcd_mat[m][n-1] > 1:
            result = (result + dp[0][m] * dp[m][n-1]) % MOD

    print(result % MOD)

if __name__ == "__main__":
    solve()

