def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    k = int(next(it))

    c = [int(next(it)) for _ in range(k)]

    # prefix sums to map bacteria number to type
    pref = [0] * (k + 1)
    for i in range(k):
        pref[i + 1] = pref[i] + c[i]

    # adjacency list for the graph
    adj = [[] for _ in range(n + 1)]
    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        x = int(next(it))
        adj[u].append((v, x))
        adj[v].append((u, x))

    # Step 1: Check if each type forms a connected component with zero-cost edges
    # We'll use DSU for zero-cost edges only
    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1

    # Union only zero-cost edges
    for u in range(1, n + 1):
        for v, w in adj[u]:
            if w == 0 and u < v:  # avoid double processing
                union(u, v)

    # Check each type: all bacteria of same type must be in same DSU component via zero-cost edges
    type_rep = [-1] * (k + 1)
    correct = True
    for typ in range(1, k + 1):
        l = pref[typ - 1] + 1
        r = pref[typ]
        if l > r:
            continue
        rep = find(l)
        for bact in range(l + 1, r + 1):
            if find(bact) != rep:
                correct = False
                break
        if not correct:
            break
        type_rep[typ] = rep

    if not correct:
        print("No")
        return

    # Step 2: Build condensed graph between types
    # Map each DSU representative to its type
    rep_to_type = {}
    for typ in range(1, k + 1):
        rep = type_rep[typ]
        if rep != -1:
            rep_to_type[rep] = typ

    # Build edges between types
    type_adj = [[] for _ in range(k + 1)]
    for u in range(1, n + 1):
        rep_u = find(u)
        typ_u = rep_to_type.get(rep_u, -1)
        if typ_u == -1:
            continue
        for v, w in adj[u]:
            rep_v = find(v)
            typ_v = rep_to_type.get(rep_v, -1)
            if typ_v == -1 or typ_u == typ_v:
                continue
            type_adj[typ_u].append((typ_v, w))

