    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    k = int(next(it))

    c = [int(next(it)) for _ in range(k)]

    # Build prefix sums to map bacteria number to type
    prefix = [0] * (k + 1)
    for i in range(k):
        prefix[i + 1] = prefix[i] + c[i]

    # Map bacteria number to type (1-indexed types)
    bact_to_type = [0] * (n + 1)
    for typ in range(1, k + 1):
        for num in range(prefix[typ - 1] + 1, prefix[typ] + 1):
            bact_to_type[num] = typ

    # Build adjacency list for the graph
    adj = [[] for _ in range(n + 1)]
    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        x = int(next(it))
        adj[u].append((v, x))
        adj[v].append((u, x))

    # Check if type-distribution is correct: within each type, all bacteria must be connected via zero-cost edges
    # We'll use DFS/BFS for each type to check connectivity via zero-cost edges only
    visited = [False] * (n + 1)

    def dfs_zero(node, typ):
        stack = [node]
        visited[node] = True
        while stack:
            cur = stack.pop()
            for neigh, cost in adj[cur]:
                if not visited[neigh] and cost == 0 and bact_to_type[neigh] == typ:
                    visited[neigh] = True
                    stack.append(neigh)

    correct = True
    for typ in range(1, k + 1):
