        first_bact = prefix[typ - 1] + 1
        if first_bact > n:
            continue
        # Reset visited for this type's bacteria
        for b in range(prefix[typ - 1] + 1, prefix[typ] + 1):
            visited[b] = False
        dfs_zero(first_bact, typ)
        # Check if all bacteria of this type are visited
        for b in range(prefix[typ - 1] + 1, prefix[typ] + 1):
            if not visited[b]:
                correct = False
                break
        if not correct:
