import re

def is_vowel(c, next_char=None):
    """Check if character c is a vowel given next_char."""
    c = c.upper()
    if c == 'Y':
        if next_char and next_char.upper() in 'AEIOU':
            return False  # Y is consonant when followed by another vowel
        return True
    return c in 'AEIOU'

def count_syllables(word):
    """Count syllables in a word according to the problem rules."""
    # Extract alphabetic part
    alphabetic = re.sub(r'[^A-Za-z]', '', word)
    if not alphabetic:
        return 1  # Non-alphabetic word still has 1 syllable

    # Convert to uppercase for processing
    chars = alphabetic.upper()
    n = len(chars)

    # Handle QU special case
    chars = chars.replace('QU', 'Q')

    # Mark vowel positions
    vowel_positions = []
    for i in range(len(chars)):
        next_char = chars[i+1] if i+1 < len(chars) else None
        if is_vowel(chars[i], next_char):
            vowel_positions.append(i)

    if not vowel_positions:
        return 1  # At least one syllable

    # Count syllable divisions
    syllables = 1
    for i in range(len(vowel_positions)-1):
        # Check if there's at least one consonant between vowels
        if vowel_positions[i+1] - vowel_positions[i] > 1:
            syllables += 1

    # Apply silent E rule
    if chars[-1] == 'E':
        if n >= 3 and chars[-2] == 'L' and not is_vowel(chars[-3], None):
            # Keep the E (e.g., 'able')
            pass
        else:
            # Silent E - remove last vowel
            if vowel_positions and vowel_positions[-1] == len(chars)-1:
                syllables = max(1, syllables - 1)

    # Apply ES rule
    if n >= 2 and chars[-2:] == 'ES':
        if n >= 3 and not is_vowel(chars[-3], None):
            # Check if preceded by at least two consonants
            cons_count = 0
            for i in range(n-3, -1, -1):
                if not is_vowel(chars[i], chars[i+1] if i+1 < n else None):
                    cons_count += 1
                else:
                    break
            if cons_count < 2:
                # ES doesn't add syllable
                if vowel_positions and vowel_positions[-1] == n-2:
                    syllables = max(1, syllables - 1)

    return max(1, syllables)

def find_haiku(words, syllables):
    """Try to split words into haiku (5-7-5 syllables)."""
    n = len(words)

    # Try all possible splits
    for i in range(1, n):
        for j in range(i+1, n):
            line1_syl = sum(syllables[:i])
            line2_syl = sum(syllables[i:j])
            line3_syl = sum(syllables[j:])

            if line1_syl == 5 and line2_syl == 7 and line3_syl == 5:
                return (
                    ' '.join(words[:i]),
                    ' '.join(words[i:j]),
                    ' '.join(words[j:])
                )
    return None

