import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    dist = [[0]*N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            dist[i][j] = int(next(it))

    # DP[mask][last]: minimum cost to visit cities in mask ending at last
    INF = 10**9
    dp = [[INF]*N for _ in range(1<<N)]

    # Initialize: starting from any city
    for i in range(N):
        dp[1<<i][i] = 0

    # Iterate over all masks
    for mask in range(1<<N):
        # For each possible last city in the current path
        for last in range(N):
            if dp[mask][last] == INF:
                continue
            # Try to add any unvisited city
            for nxt in range(N):
                if mask & (1<<nxt):
                    continue  # already visited
                new_mask = mask | (1<<nxt)
                new_cost = dp[mask][last] + dist[last][nxt]
                if new_cost < dp[new_mask][nxt]:
                    dp[new_mask][nxt] = new_cost

    # Find minimum cost among all full tours ending at any city
    full_mask = (1<<N) - 1
    ans = min(dp[full_mask][i] for i in range(N))
    print(ans)

