    while start <= n:
        end = min(n, 10**length - 1)
        count = end - start + 1
        total += count * length
        start = 10**length
        length += 1

    return total

def find_block(k):
    """Find which block (1-based) contains position k"""
    low, high = 1, int(1e9)

    while low <= high:
        mid = (low + high) // 2
        # Calculate total digits up to block mid
        total = 0
        for i in range(1, mid + 1):
            total += total_digits_up_to_n(i)
            if total >= k:
                break

        if total >= k:
            high = mid - 1
        else:
            low = mid + 1

    return low

def find_number_in_sequence(k):
    """Find the number at position k in the sequence"""
    # First find which block
    block = find_block(k)

    # Calculate cumulative digits before this block
    cum_digits = 0
    for i in range(1, block):
        cum_digits += total_digits_up_to_n(i)

    # Position within the current block
    pos_in_block = k - cum_digits

    # Now find which number in the block contains this position
    low, high = 1, block

    while low <= high:
