    if len(minus_candidates) == 0:
        minus_results.append("<empty>")
    elif len(minus_candidates) == 1:
        enc = next(iter(minus_candidates))
        minus_results.append(enc if enc else "<empty>")
    else:
        minus_results.append("<any>")

    # Output all combinations
    for p in plus_results:
        for m in minus_results:
            print(f"{p} {m}")

