class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.empty = [True] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        root_x = self.find(x)
        root_y = self.find(y)

        if root_x == root_y:
            return root_x

        if self.size[root_x] < self.size[root_y]:
            root_x, root_y = root_y, root_x

        self.parent[root_y] = root_x
        self.size[root_x] += self.size[root_y]
        self.empty[root_x] = self.empty[root_x] or self.empty[root_y]
        return root_x

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    N = int(next(it))
    L = int(next(it))

    uf = UnionFind(L)
    result = []

    for i in range(N):
        a = int(next(it)) - 1
        b = int(next(it)) - 1

        root_a = uf.find(a)
        root_b = uf.find(b)

        stored = False

        if uf.empty[root_a]:
            uf.empty[root_a] = False
            stored = True
        elif uf.empty[root_b]:
            uf.empty[root_b] = False
            stored = True
        elif root_a != root_b:
            new_root = uf.union(a, b)
            if uf.empty[new_root]:
                uf.empty[new_root] = False
                stored = True

        if stored:
            result.append("LADICA")
        else:
            result.append("SMECE")

    sys.stdout.write("\n".join(result))

