    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    k = int(next(it))

    # Read instructions: instructions[i][j] for core i (0-indexed) at cycle j (0-indexed)
    instructions = []
    for _ in range(n):
        row = [int(next(it)) for _ in range(m)]
        instructions.append(row)

    # Track locked cores and cells
    locked_cores = [False] * n
    locked_cells = [False] * (k + 1)  # 1-indexed for cells
    lock_cycle = [0] * n  # 0 means not locked

    # Simulate each cycle
    for cycle in range(m):
        # For each core
        for core in range(n):
            if locked_cores[core]:
                continue  # Already locked, ignore

            instr = instructions[core][cycle]
            if instr == 0:
                continue  # Do nothing

            # Write to cell instr
            cell = instr
            if locked_cells[cell]:
                # Cell is already locked, this core locks now
                locked_cores[core] = True
                lock_cycle[core] = cycle + 1  # 1-indexed cycle number
            else:
                # Check if any other core writes to same cell this cycle
                conflict = False
                for other_core in range(n):
                    if other_core == core or locked_cores[other_core]:
                        continue
                    if instructions[other_core][cycle] == cell:
                        conflict = True
                        break

                if conflict:
                    # All cores writing to this cell this cycle get locked
                    for c in range(n):
                        if locked_cores[c]:
                            continue
                        if instructions[c][cycle] == cell:
                            locked_cores[c] = True
                            lock_cycle[c] = cycle + 1
                    # Cell also gets locked
                    locked_cells[cell] = True
                else:
                    # No conflict, write succeeds (but we don't need to track content)
                    pass

    # Output
    for i in range(n):
        print(lock_cycle[i])

