import sys
import itertools

def rotate(grid):
    """Rotate 90 degrees clockwise."""
    h, w = len(grid), len(grid[0])
    return [''.join(grid[h-1-j][i] for j in range(h)) for i in range(w)]

def all_rotations(grid):
    """Generate all 4 rotations of a grid."""
    rots = []
    current = grid
    for _ in range(4):
        rots.append(current)
        current = rotate(current)
    return rots

def solve():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    N = int(data[0])
    idx = 1
    pieces = []
    for i in range(N):
        w, h = map(int, data[idx].split())
        idx += 1
        grid = data[idx:idx+h]
        idx += h
        pieces.append((w, h, grid, i+1))

    # Try all permutations of pieces
    for perm in itertools.permutations(range(N)):
        # Try all rotations for each piece in this permutation
        rotations = []
        for p_idx in perm:
            w, h, grid, _ = pieces[p_idx]
            rotations.append(all_rotations(grid))

        # Try all combinations of rotations
        for rot_combo in itertools.product(*rotations):
            # Determine dimensions of reconstructed map
            total_cells = sum(len(r)*len(r[0]) for r in rot_combo)
            # Try all possible rectangle dimensions
            for H in range(1, total_cells+1):
                if total_cells % H != 0:
                    continue
                W = total_cells // H
                if W == 0:
                    continue

                # Try to place pieces
                board = [['.' for _ in range(W)] for _ in range(H)]
                piece_board = [['.' for _ in range(W)] for _ in range(H)]
                placed = [False]*N

                def backtrack(pos):
                    if pos == N:
                        # All pieces placed, check if board is full
                        for i in range(H):
                            for j in range(W):
                                if board[i][j] == '.':
                                    return False
                        return True

                    p_idx = perm[pos]
                    rot_grid = rot_combo[pos]
                    h_rot, w_rot = len(rot_grid), len(rot_grid[0])

                    # Try all positions for this piece
                    for y in range(H - h_rot + 1):
                        for x in range(W - w_rot + 1):
                            # Check if piece fits
                            ok = True
                            for dy in range(h_rot):
                                for dx in range(w_rot):
                                    if board[y+dy][x+dx] != '.':
                                        ok = False
                                        break
                                if not ok:
                                    break

                            if ok:
                                # Place piece
                                for dy in range(h_rot):
                                    for dx in range(w_rot):
                                        board[y+dy][x+dx] = rot_grid[dy][dx]
                                        piece_board[y+dy][x+dx] = str(pieces[p_idx][3])

                                if backtrack(pos+1):
                                    return True

                                # Remove piece
                                for dy in range(h_rot):
                                    for dx in range(w_rot):
                                        board[y+dy][x+dx] = '.'
                                        piece_board[y+dy][x+dx] = '.'
                    return False

                if backtrack(0):
                    # Output solution
                    print(f"{W} {H}")
                    for row in board:
                        print(''.join(row))
                    print('-' * W)
                    for row in piece_board:
                        print(''.join(row))
                    return

