                if seg_start <= last_end + 1:
                    merged[-1][1] = max(last_end, seg_end)
                else:
                    merged.append([seg_start, seg_end])

        # Remove blocked cells in next row
        final_segments = []
        for seg_start, seg_end in merged:
            if seg_start > n or seg_end < 1:
