import sys

def solve():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return "impossible"

    idx = 0
    N = int(data[idx]); idx += 1
    K = int(data[idx]); idx += 1

    # inventory[store] = set of items available at that store
    inventory = [set() for _ in range(N)]
    # item_to_stores[item] = list of stores that have this item
    item_to_stores = {}

    for _ in range(K):
        store_str, item = data[idx].split(); idx += 1
        store = int(store_str)
        inventory[store].add(item)
        if item not in item_to_stores:
            item_to_stores[item] = []
        item_to_stores[item].append(store)

    M = int(data[idx]); idx += 1
    bought_items = []
    for _ in range(M):
        bought_items.append(data[idx]); idx += 1

    # Early check: all bought items must exist in some store
    for item in bought_items:
        if item not in item_to_stores:
            return "impossible"

    # DP approach: dp[i][store] = number of ways to assign first i items
    # such that the i-th item is bought at store 'store'
    # We only need to keep track of previous row

    # Initialize for first item
    first_item = bought_items[0]
    possible_stores = item_to_stores[first_item]
    if not possible_stores:
        return "impossible"

    # prev_ways[store] = number of ways for previous item at store
    prev_ways = {store: 1 for store in possible_stores}

    # For each subsequent item
    for i in range(1, M):
        item = bought_items[i]
        stores_for_item = item_to_stores[item]

        # Build current ways
        curr_ways = {}

        # For each possible store for current item
        for store in stores_for_item:
            total = 0
            # Sum ways from all previous stores that are <= current store
            # (since sister visits stores in increasing order)
            for prev_store, ways in prev_ways.items():
                if prev_store <= store:
                    total += ways
                    # Early stop if we already have more than 1 way
                    if total > 1:
                        break
            if total > 0:
                curr_ways[store] = total

        if not curr_ways:
            return "impossible"

        # Update prev_ways for next iteration
        prev_ways = curr_ways

    # Sum all ways for the last item
    total_ways = sum(prev_ways.values())

    if total_ways == 0:
        return "impossible"
    elif total_ways == 1:
        return "unique"
    else:
        return "ambiguous"

if __name__ == "__main__":
    print(solve())

