def is_inside(x, y, rect):
    """Check if point (x,y) is strictly inside rectangle rect=(x1,y1,x2,y2)"""
    x1, y1, x2, y2 = rect
    return x1 < x < x2 and y1 < y < y2

def is_on_boundary(x, y, rect):
    """Check if point (x,y) is on the boundary of rectangle rect"""
    x1, y1, x2, y2 = rect
    return (x1 <= x <= x2 and (y == y1 or y == y2)) or (y1 <= y <= y2 and (x == x1 or x == x2))

