    corners = [(x1, y1), (x1, y2), (x2, y1), (x2, y2)]

    for x, y in corners:
        # Point must be not strictly inside white (so on boundary is OK)
        # and strictly outside both black sheets
        if not is_inside(x, y, white):  # on boundary or outside
            if not is_inside(x, y, black1) and not is_inside(x, y, black2):
                # Also check it's not on boundary of black sheets
                if not is_on_boundary(x, y, black1) and not is_on_boundary(x, y, black2):
