def solve():
    n, q = map(int, input().split())
    a = list(map(int, input().split()))

    # Step 1: Validate non-zero constraints
    # For each query i, track the first and last occurrence in the original array
    first = [n + 1] * (q + 1)
    last = [0] * (q + 1)

    for idx, val in enumerate(a):
        if val != 0:
            first[val] = min(first[val], idx)
            last[val] = max(last[val], idx)

    # Check if query q appears (required by problem statement)
    if first[q] == n + 1 and last[q] == 0:
        # Try to place query q in a zero position
        placed = False
        for i in range(n):
            if a[i] == 0:
                a[i] = q
                first[q] = last[q] = i
                placed = True
                break
        if not placed:
            print("NO")
            return

    # Step 2: Validate ordering constraints for non-zero values
    # Use a stack to track active queries
    stack = []
    for idx, val in enumerate(a):
        if val != 0:
            # Check if this value violates the stack order
            while stack and stack[-1] > val:
                print("NO")
                return
            if not stack or stack[-1] != val:
                stack.append(val)

    # Step 3: Fill zeros with appropriate values
    # Create an array to store the latest covering query for each position
    cover = [0] * n

    # Process queries in order to build coverage
    # We'll use the first/last occurrences to determine coverage
    for query in range(1, q + 1):
        if first[query] <= last[query]:  # Query appears in array
            # Mark all positions between first and last as covered by this query
            for pos in range(first[query], last[query] + 1):
                cover[pos] = max(cover[pos], query)

    # Fill zeros using the coverage array
    result = a[:]
    for i in range(n):
        if result[i] == 0:
            # Find nearest non-zero neighbors to determine appropriate value
            left_val = 0
            for j in range(i - 1, -1, -1):
                if result[j] != 0:
                    left_val = result[j]
                    break

            right_val = 0
            for j in range(i + 1, n):
                if result[j] != 0:
                    right_val = result[j]
                    break

            # Choose the maximum of left neighbor, right neighbor, and coverage
            candidates = [cover[i]]
            if left_val != 0:
                candidates.append(left_val)
            if right_val != 0:
                candidates.append(right_val)

            if candidates:
                result[i] = max(candidates)
            else:
                # Should not happen since every position must be covered
                result[i] = 1

    # Step 4: Final validation
    # Check that every position has value between 1 and q
    for val in result:
        if val < 1 or val > q:
            print("NO")
            return

    # Check that query q appears in the result
    if q not in result:
        print("NO")
        return

    # Verify the result can be produced by the query process
    # Reconstruct coverage from result to validate
    test_first = [n + 1] * (q + 1)
    test_last = [0] * (q + 1)
    for idx, val in enumerate(result):
        test_first[val] = min(test_first[val], idx)
        test_last[val] = max(test_last[val], idx)

    # Check ordering constraints
    for query in range(1, q + 1):
        if test_first[query] <= test_last[query]:
            # All values between first and last should be >= query
            for pos in range(test_first[query], test_last[query] + 1):
                if result[pos] < query:
                    print("NO")
                    return

    print("YES")
    print(' '.join(map(str, result)))

if __name__ == "__main__":
    solve()

