import sys

def read_input():
    """Read input from stdin."""
    data = sys.stdin.read().strip().split()
    if not data:
        return None
    return list(map(int, data))

def die_range_to_list(a, b):
    """Convert die range [a,b] to list of possible values."""
    return list(range(a, b + 1))

def compute_probabilities(dice1, dice2):
    """Compute probability distribution of sum for two dice."""
    sums = {}
    total_outcomes = len(dice1) * len(dice2)
    for d1 in dice1:
        for d2 in dice2:
            s = d1 + d2
            sums[s] = sums.get(s, 0) + 1
    # Convert to probabilities
    return {s: count / total_outcomes for s, count in sums.items()}

def compare_probabilities(gunnar_probs, emma_probs):
    """Compare probabilities of winning."""
    gunnar_win_prob = 0.0
    emma_win_prob = 0.0

    for g_sum, g_prob in gunnar_probs.items():
        for e_sum, e_prob in emma_probs.items():
            if g_sum > e_sum:
                gunnar_win_prob += g_prob * e_prob
            elif e_sum > g_sum:
                emma_win_prob += g_prob * e_prob

    if abs(gunnar_win_prob - emma_win_prob) < 1e-9:
        return "Tie"
    elif gunnar_win_prob > emma_win_prob:
        return "Gunnar"
    else:
        return "Emma"

def main():
    data = read_input()
    if data is None:
        return

    # Parse input
    a1, b1, a2, b2 = data[0:4]
    a3, b3, a4, b4 = data[4:8]

    # Create dice
    gunnar_die1 = die_range_to_list(a1, b1)
    gunnar_die2 = die_range_to_list(a2, b2)
    emma_die1 = die_range_to_list(a3, b3)
    emma_die2 = die_range_to_list(a4, b4)

    # Compute probability distributions
    gunnar_probs = compute_probabilities(gunnar_die1, gunnar_die2)
    emma_probs = compute_probabilities(emma_die1, emma_die2)

    # Compare and output result
    result = compare_probabilities(gunnar_probs, emma_probs)
    print(result)

if __name__ == "__main__":
    main()

