import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return "NO"
    it = iter(data)
    n = int(next(it))
    k = int(next(it))

    # Since k ≤ 4, there are at most 2^k = 16 possible problem types
    # Count how many problems of each type we have
    cnt = [0] * (1 << k)
    for _ in range(n):
        mask = 0
        for j in range(k):
            bit = int(next(it))
            if bit:
                mask |= (1 << j)
        cnt[mask] += 1

    # Case 1: If there exists a problem that no team knows (mask = 0)
    if cnt[0] > 0:
        return "YES"

    # Case 2: If there exist two problems such that for every team,
    # at least one of the two problems is unknown to that team
    # This means (mask1 & mask2) == 0
    for mask1 in range(1, 1 << k):
        if cnt[mask1] == 0:
            continue
        for mask2 in range(mask1 + 1, 1 << k):
            if cnt[mask2] == 0:
                continue
            if (mask1 & mask2) == 0:
                return "YES"

    # Case 3: If k ≤ 3, we can also consider single problems where
    # no team knows more than half (but we already checked mask=0)
    # For k=4, we need to check if there's a problem where at most 2 teams know it
    # (since half of 4 is 2)
    for mask in range(1, 1 << k):
        if cnt[mask] == 0:
            continue
        # Count how many teams know this problem
        known_teams = bin(mask).count('1')
        if known_teams <= k // 2:
            return "YES"

    return "NO"

if __name__ == "__main__":
    print(solve())

