import math

def find_binomial_coefficient(X):
    """Find n and k such that C(n,k) = X with minimal n, then minimal k."""
    # Handle edge cases
    if X == 1:
        return (1, 0)  # C(1,0) = 1, C(1,1) = 1, but (1,0) has smaller k

    # For X up to 10^100, we need to handle large integers
    X_int = int(X)

    # Try increasing n values
    n = 1
    while True:
        # For each n, try k from 0 to n//2 (symmetry)
        for k in range(0, n // 2 + 1):
            # Compute C(n,k) efficiently
            coeff = 1
            # Use multiplicative formula to avoid overflow
            for i in range(1, k + 1):
                coeff = coeff * (n - k + i) // i
                if coeff > X_int:
                    break

            if coeff == X_int:
                # Found a solution
                return (n, k)

            # Check symmetric k' = n-k
            if k != n - k:
                coeff_sym = 1
                for i in range(1, n - k + 1):
                    coeff_sym = coeff_sym * (k + i) // i
                    if coeff_sym > X_int:
                        break

                if coeff_sym == X_int:
                    return (n, n - k)

        n += 1
        # Safety check: if n becomes too large without finding solution
        if n > 2 * X_int + 10:  # Rough upper bound
            break

    # Fallback (should not reach here for valid inputs)
    return (X_int, 1)

def main():
    # Read input
    X = sys.stdin.read().strip()
    if not X:
        return

    n, k = find_binomial_coefficient(X)
