        # Find the smallest value we can bring to position i
        best_val = p[i]
        best_idx = i
        for j in range(i+1, n):
            if reach[i][j] and p[j] < best_val:
                best_val = p[j]
                best_idx = j
        # Swap if beneficial
        if best_idx != i:
            p[i], p[best_idx] = p[best_idx], p[i]

